Z=lambda q,a:[('z',q),('b',a)]
def palms(): return '<path d="M-6 0 q-8 -30 2 -60 q4 -6 4 0 v60z M6 0 q8 -30 -2 -60 q-4 -6 -4 0 v60z" fill="#e8c3a0" stroke="#b08060" stroke-width="1.5"/>'
