fw=foreword(i,['Two palms pressed together at the chest, a slight bow of the head: <b>namaskāra</b> is the most familiar Hindu gesture, used for God, for elders and for a stranger at the door. In the temple it can grow into a full-length prostration on the floor; before an elder it becomes a touch of the feet.',
 'This part explains the word, the joined palms, the levels of the gesture, the full prostration and its eight limbs, touching elders’ feet and their blessing, the formal greeting with one’s lineage, namaskāra to the sun, the earth and the stage, and what it means.',
 'Previous: '+L('/why-do-we/pradakshina/','pradakṣiṇā')+'. Next: '+L('/why-do-we/tulasi/','tulasī')+'.'],Z('Is namaste the same as namaskāra?','Namaste is what you say; namaskāra is what you do. Same bow.'))
gl=glance([('Word','Namaskāra, from namaḥ: “bow, salutation”'),('Saying','Namaste / namaskāra: “I bow to you”'),('Hands','Añjali: palms joined, fingers up'),('Levels','Chest (people), face (teachers), above head (God), by custom'),('Full bow','Sāṣṭāṅga: eight limbs touching the ground'),('Kneeling','Pañcāṅga: five limbs, common for women by custom'),('Elders','Touching the feet; receiving a blessing'),('Formal','Abhivādana: greeting with one’s lineage name'),('Also to','The sun, the earth, the stage, books, tools'),('Meaning','Humility; seeing the divine in the other')],
 S('A person with joined palms, another in full prostration, a third touching an elder’s feet',g(110,215,1.5,person('#c0392b'))+g(110,150,.6,palms())+g(290,210,1.3,prone())+g(450,215,1.4,person('#f4f1ea'))+g(500,215,1,'<rect x="-14" y="-30" width="28" height="30" fill="#1d4f8a"/><circle cy="-38" r="9" fill="#e8c3a0"/>'),'#fff3cf',215),Z('Are there rules for it?','Some, by custom. The bow matters more than the rules.'),'The bow <b>of joined hands</b>.')
word=reading('word','THE WORD','Namaḥ: I bow',S('The word namaḥ written large above two joined palms',g(280,215,2.4,palms())+T(280,60,'namaḥ',28),'#fff3cf',215),
 ['<b>Namaḥ.</b> Sanskrit namaḥ (from the root nam, to bend) means a bow or salutation.','<b>Namaste.</b> Namaḥ + te: “a bow to you”.','<b>Namaskāra.</b> Namaḥ + kāra, “making”: the act of bowing.','<b>In mantras.</b> Namaḥ appears in countless prayers: “Oṃ namaḥ Śivāya”, salutations to Śiva.','<b>Regional.</b> Kannaḍa namaskāra, Tamiḻ vaṇakkam, Hindi namaste, praṇām.'],Z('So “namaḥ” is in every prayer?','Very many. Before you ask the god anything, you bow.'),'First <b>bend</b>.')
anj=reading('anjali','AÑJALI','The joined palms',S('Close-up of joined palms before the chest',g(280,220,3,palms()),'#fff3cf',230),
 ['<b>Añjali mudrā.</b> The palms are pressed together, fingers pointing up, thumbs near the chest.','<b>Offering.</b> Añjali also means a double handful offered; the gesture is like holding out an offering. (Common explanation.)','<b>Two made one.</b> Teachers read the two palms as two persons, or self and God, meeting. (Interpretation.)','<b>Empty hands.</b> Joined palms hold no weapon: a gesture of peace. (Common explanation.)','<b>In art.</b> Devotees, Garuḍa and Hanumān are shown with joined palms before the god.'],Z('Does the left or right go in front?','Neither. Palm to palm, evenly.'),'Two hands, <b>one gesture</b>.')
lev=cards('levels','HOW HIGH','Levels of the gesture',fig_row('Three figures with palms at chest, at face, and above the head',[(person('#1d4f8a')+g(0,-46,.4,palms()),1.1),(person('#c0392b')+g(0,-62,.4,palms()),1.1),(person('#2a9d6f')+g(0,-90,.4,palms()),1.1)],['chest','face','above head'],gy=150),
 [('🙏','Chest','Greeting equals, guests, strangers.'),('🧑‍🏫','Face','For teachers and elders, in some customs.'),('🛕','Above the head','Before God, in many customs.'),('🙇','With a bow','Head bowed adds humility at any level.'),('👀','Eyes closed','Often closed before God, open to people.'),('🧭','Customs differ','These are common customs, not fixed laws.')],None,'Higher hands, <b>deeper bow</b>.',intro='Many communities teach these levels; practice varies.')
ast=reading('sashtanga','SĀṢṬĀṄGA','The full prostration',S('A man lying full length face down before a shrine with arms stretched out',g(300,210,1.8,prone())+g(500,215,1,'<rect x="-30" y="-60" width="60" height="60" fill="#e9d6c0"/><path d="M-36 -60 L0 -90 L36 -60z" fill="#7a3b1f"/>'),'#fff3cf',215),
 ['<b>Eight limbs.</b> Sāṣṭāṅga means “with eight limbs”: the body touches the ground at many points while mind, speech and sight are also offered. (Lists of the eight differ.)','<b>Like a stick.</b> It is also called daṇḍa-praṇāma: falling flat like a stick.','<b>Where.</b> In temples, before the guru and before parents on special days.','<b>Not inside the sanctum.</b> In many temples it is done outside the sanctum door, toward the god.','<b>Rising.</b> One rises slowly and joins the palms.'],Z('Like a stick?','Fall straight, without holding anything back. That is the idea.'),'Fall <b>like a stick</b>.')
pan=reading('panchanga','PAÑCĀṄGA','The kneeling bow',S('A woman kneeling with forehead to the floor and palms joined forward',g(280,210,1.4,'<path d="M-40 0 q20 -40 50 -30 l30 30z" fill="#c0392b"/><circle cx="50" cy="-6" r="9" fill="#e8c3a0"/><path d="M60 -4 h30" stroke="#e8c3a0" stroke-width="5"/>'),'#fff3cf',215),
 ['<b>Five limbs.</b> Pañcāṅga: the knees, the hands and the forehead touch the ground.','<b>By custom.</b> In many traditions women bow this way rather than lying full length.','<b>Same honour.</b> It carries the same reverence as the full prostration.','<b>Everyone.</b> Men too use it where space is short.','<b>At home.</b> Many families end the daily pūjā with a kneeling bow.'],Z('Why different for women?','Custom, and dress. The reverence is the same.'),'A bow <b>on the knees</b>.')
feet=reading('feet','TOUCHING THE FEET','The elders’ blessing',S('A young man bending to touch an elder’s feet; the elder’s hand raised in blessing',g(320,215,1.6,person('#f4f1ea'))+g(220,215,1.2,'<path d="M-20 0 q0 -40 30 -50" stroke="#1d4f8a" stroke-width="18" fill="none"/><circle cx="16" cy="-50" r="9" fill="#e8c3a0"/>')+'<path d="M340 120 l20 -20" stroke="#e8c3a0" stroke-width="6"/>','#fff3cf',215),
 ['<b>The gesture.</b> Bending to touch the feet of parents, grandparents, teachers and holy people.','<b>When.</b> At festivals, birthdays, before exams, journeys and weddings, and on meeting after a long time.','<b>Blessing.</b> The elder places a hand on the head and blesses: long life, success.','<b>Why the feet.</b> The feet are the humblest part; touching them shows humility, and the elder’s grace is said to flow back. (Common explanation.)','<b>Children.</b> Families teach it early.'],Z('What if the elder says “no, no”?','They always say that. Do it anyway, gently.'),'Humility <b>returned as blessing</b>.')
abh=reading('abhivadana','ABHIVĀDANA','The formal greeting',S('A young man introducing himself with joined palms to a teacher',g(200,215,1.4,person('#1d4f8a'))+g(200,150,.5,palms())+g(400,215,1.4,person('#f4f1ea',seat=True))+'<rect x="230" y="80" width="140" height="40" rx="10" fill="#fff8e7" stroke="#7a3b1f"/>'+T(300,105,'lineage · name',10),'#fff3cf',215),
 ['<b>Abhivādana.</b> In traditional settings, a formal greeting to a teacher or elder in which one states one’s lineage (ṛṣis and gotra), Veda branch and name.','<b>Who.</b> Kept mainly in Vedic families, maṭhas and pāṭhaśālās.','<b>Then the bow.</b> The greeting is followed by touching the feet or a full bow.','<b>Reply.</b> The elder answers with a blessing.','<b>Here.</b> We describe it; the exact formula is learned from one’s family or teacher.'],Z('Why say your ancestors’ names?','So the teacher knows whose child stands before him. You bring your line with you.'),'You bow <b>with your whole line</b>.')
others=cards('others','NAMASKĀRA TO ALL','Sun, earth, stage, tools',fig_row('The sun, the earth, a dance stage and books',[('<circle r="18" fill="#f0c030"/>',1.2),('<path d="M-30 0 h60" stroke="#8a6a3a" stroke-width="10"/>',1.2),('<rect x="-30" y="-20" width="60" height="20" fill="#7a3b1f"/>',1.2),('<rect x="-20" y="-24" width="40" height="24" fill="#fff8e7" stroke="#7a3b1f"/>',1.2)],['sun','earth','stage','books'],gy=150),
 [('☀️','Sūrya namaskāra','A sequence of postures saluting the sun, practised in yoga.'),('🌍','The earth','Many touch the ground on waking, asking pardon for stepping on her.'),('💃','The stage','Dancers and musicians bow to the stage and instruments before performing.'),('📚','Books','A book touched by the foot is touched to the forehead.'),('🛠️','Tools','Tools and vehicles are honoured at Āyudha Pūjā.'),('🙏','Every person','Namaste to anyone: the divine in all.')],None,'Everything <b>worthy of a bow</b>.')
st=story('story','THE BOW','Kavya’s exam morning',strip('Three panels: a girl ready with her bag; she touches her grandmother’s feet; the grandmother blesses her',
 [('<rect width="144" height="190" fill="#fff3cf"/>'+g(72,180,.8,person('#1d4f8a'))+'<rect x="84" y="130" width="20" height="24" fill="#c0392b"/>','#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(100,180,.8,person('#f4f1ea'))+g(50,180,.6,'<path d="M-10 0 q0 -30 20 -36" stroke="#1d4f8a" stroke-width="12" fill="none"/>'),'#fff3cf'),
  ('<rect width="144" height="190" fill="#fff3cf"/>'+g(90,180,.8,person('#f4f1ea'))+g(50,180,.7,person('#1d4f8a'))+'<path d="M90 110 l-26 0" stroke="#e8c3a0" stroke-width="5"/>','#fff3cf')],['ready','the bow','the blessing']),'A family morning (an illustrative story).',
 ['Kavya has her exam. Bag packed, pens checked.','At the door she stops and bends to touch Ajji’s feet.','Ajji puts a hand on her head: “Go well, come back well.” Kavya walks out lighter.'])
mean=reading('meaning','WHAT IT MEANS','Humility and the divine in all',S('Two people greeting each other with namaste, a small flame between them',g(180,215,1.5,person('#c0392b'))+g(180,150,.6,palms())+g(380,215,1.5,person('#1d4f8a'))+g(380,150,.6,palms())+g(280,150,.8,flame()),'#fff3cf',215),
 ['<b>Humility.</b> Bowing lowers the head and the ego. (Common teaching.)','<b>The divine in the other.</b> Namaste is often read as “the divine in me bows to the divine in you”. (Modern interpretation, widely used.)','<b>Respect.</b> It shows respect without touching, suitable for anyone.','<b>Surrender.</b> Before God, the full prostration is surrender of the whole self.','<b>Gratitude.</b> To parents, teachers, earth and sun: thanks.'],Z('Is the “divine in you” meaning in the texts?','It is a modern reading of an old gesture. A good one.'),'Bow, <b>and see God in the other</b>.')
endp=end(i,['<b>Word.</b> Namaskāra, namaste: “I bow to you”.','<b>Gesture.</b> Añjali, the joined palms; levels by custom.','<b>Prostration.</b> Sāṣṭāṅga (eight limbs) and pañcāṅga (kneeling).','<b>Elders.</b> Touching the feet; abhivādana with one’s lineage.','<b>Meaning.</b> Humility, respect, the divine in all.'],'Part 8 is tulasī.','The bow of joined hands')
